import { getInputForDay } from '../../helpers/getInputForDay';
import { showTheResult } from '../../helpers/showTheResult';

(async () => {
  console.time('time');
  const input = (await getInputForDay(__filename)).split('\n');

  // --- Parse the shapes section -------------------------------------------
  // Each shape is "index:" followed by 3 grid rows, separated by blank lines.
  // We only need each shape's area (number of '#' cells).
  const shapeAreas: number[] = [];

  let i = 0;
  while (i < input.length) {
    const line = input[i].trim();
    const shapeMatch = line.match(/^(\d+):$/);
    if (!shapeMatch) break;

    const index = +shapeMatch[1];
    const rows = input.slice(i + 1, i + 4).map((r) => r.trim());
    const area = rows
      .join('')
      .split('')
      .filter((ch) => ch === '#').length;

    shapeAreas[index] = area;
    i += 5; // index line + 3 grid rows + 1 blank line
  }

  // --- Parse the regions section ------------------------------------------
  // Each region is "WxL: q0 q1 q2 q3 q4 q5".
  let fittingRegions = 0;

  for (let j = i; j < input.length; j++) {
    const line = input[j].trim();
    if (!line) continue;

    const match = line.match(/^(\d+)x(\d+):\s*(.+)$/);
    if (!match) continue;

    const width = +match[1];
    const length = +match[2];
    const quantities = match[3].trim().split(/\s+/).map(Number);

    const areaNeeded = quantities.reduce(
      (sum, count, shapeIndex) => sum + count * (shapeAreas[shapeIndex] ?? 0),
      0,
    );

    if (areaNeeded <= width * length) fittingRegions += 1;
  }

  showTheResult({ star1: fittingRegions, star2: 'WIP...', path: __filename });
  console.timeEnd('time');
})();
